code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    ray_color = min((v for v in counts if v != background), key=lambda v: counts[v])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == ray_color]

    # Edge bars are contiguous non-background runs of length at least two.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == background:
                c += 1
                continue
            color = grid[r][c]
            start = c
            while c < w and grid[r][c] == color:
                c += 1
            if c - start >= 2:
                bars.append(("h", r, start, c - 1))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == background:
                r += 1
                continue
            color = grid[r][c]
            start = r
            while r < h and grid[r][c] == color:
                r += 1
            if r - start >= 2:
                bars.append(("v", c, start, r - 1))

    # Markers positioned within the span of a bar set the lanes; reuse the same
    # lane offsets at every edge bar of the same orientation.
    lane_offsets = {"h": set(), "v": set()}
    for orient, edge, start, end in bars:
        for r, c in markers:
            axis = c if orient == "h" else r
            if start <= axis <= end:
                lane_offsets[orient].add(axis - start)

    for orient, edge, start, end in bars:
        offsets = lane_offsets[orient]
        if not offsets:
            continue
        if orient == "h":
            dr = 1 if edge == 0 else -1
            for offset in offsets:
                c = start + offset
                r = edge + dr
                while 0 <= r < h:
                    if grid[r][c] == ray_color:
                        out[r][c] = 4
                        break
                    out[r][c] = ray_color
                    r += dr
        else:
            dc = 1 if edge == 0 else -1
            for offset in offsets:
                r = start + offset
                c = edge + dc
                while 0 <= c < w:
                    if grid[r][c] == ray_color:
                        out[r][c] = 4
                        break
                    out[r][c] = ray_color
                    c += dc
    return out
'''
